#!/usr/bin/env pwsh\n# Deploy to GitHub Pages\n# Usage: .\deploy-github-pages.ps1 -GitHubUser \"tu_usuario\" -RepoName \"telegram-agent-ui\"\n\nparam(\n    [Parameter(Mandatory=$true)]\n    [string]$GitHubUser,\n    \n    [Parameter(Mandatory=$true)]\n    [string]$RepoName\n)\n\n$ErrorActionPreference = \"Stop\"\n\nWrite-Host \"🚀 Iniciando deployment a GitHub Pages...\" -ForegroundColor Cyan\n\n# 1. Build Docusaurus\nWrite-Host \"`n📦 Compilando Docusaurus...\" -ForegroundColor Yellow\nSet-Location docusaurus\nnpm run build\nif ($LASTEXITCODE -ne 0) {\n    Write-Host \"Error en build. Abortando.\" -ForegroundColor Red\n    exit 1\n}\n\n# 2. Volver a raiz\nSet-Location ..\n\n# 3. Verificar si el remote existe\nWrite-Host \"`n🔗 Configurando remote de GitHub...\" -ForegroundColor Yellow\n$remoteExists = git remote | Select-String -Pattern \"origin\"\nif ($remoteExists) {\n    Write-Host \"Remote 'origin' ya existe.\"\n} else {\n    $gitUrl = \"https://github.com/$GitHubUser/$RepoName.git\"\n    Write-Host \"Agregando remote: $gitUrl\"\n    git remote add origin $gitUrl\n}\n\n# 4. Agregar cambios\nWrite-Host \"`n📝 Agregando cambios a git...\" -ForegroundColor Yellow\ngit add .\n\n# 5. Commit\nWrite-Host \"`n✍️  Haciendo commit...\" -ForegroundColor Yellow\n$timestamp = Get-Date -Format \"yyyy-MM-dd HH:mm:ss\"\ngit commit -m \"Deployment to GitHub Pages: $timestamp\" --allow-empty\n\n# 6. Push\nWrite-Host \"`n⬆️  Push a GitHub...\" -ForegroundColor Yellow\n$branch = git rev-parse --abbrev-ref HEAD\ngit push -u origin $branch\n\nif ($LASTEXITCODE -eq 0) {\n    $pageUrl = \"https://$GitHubUser.github.io/$RepoName\"\n    Write-Host \"`n✅ Deployment exitoso!\" -ForegroundColor Green\n    Write-Host \"📍 Tu sitio estará disponible en: $pageUrl\" -ForegroundColor Green\n    Write-Host \"   (puede tomar 1-2 minutos en aparecer)\" -ForegroundColor Gray\n} else {\n    Write-Host \"`n❌ Error en push. Verifica tus credenciales.\" -ForegroundColor Red\n    exit 1\n}\n